//each function name should be prefixed by em_

static inline int em_check_ngap_message_type(int message_type) {
  // Define the range of NGSetupRequest message types considered normal.  Adjust as needed.
  if (message_type >= 1 && message_type <= 5) { //Example: NGSetupRequest messages 1-5 are normal
    return 0;
  } else {
    return 1;
  }
}
